-- Repairs the editorial profiles of Builds #131/#132: Sql-OnPrem.ps1 sent their accented text as '?'
-- (PowerShell 5.1 ASCII pipe). Rewrites the original text from the release sources. Data-only, idempotent.
\set ON_ERROR_STOP on
BEGIN;
UPDATE editorial_profiles SET ownership_type='Association de journalistes (organisation de la société civile)', owner='Cambodian Journalists Alliance Association (CamboJA)', historical_context='Site d''information de l''Association de l''alliance des journalistes cambodgiens (CamboJA), basée à Phnom Penh.',
  current_context='Actualité nationale cambodgienne en anglais : enquêtes, reportages spéciaux, résumé hebdomadaire.', evidence_summary='Le site s''identifie comme publié par la Cambodian Journalists Alliance Association et se présente comme une source d''information « indépendante » ; financement et gouvernance non vérifiés pour ce profil.', evidence_sources='[{"url":"https://cambojanews.com/about/","note":"Mentions éditeur : Cambodian Journalists Alliance Association","category":"self_description","accessed_at":"2026-11-02"},{"url":"https://www.camboja.net/","note":"Site de l''association CamboJA","category":"self_description","accessed_at":"2026-11-02"}]'::jsonb
  WHERE publisher_id=(SELECT id FROM publishers WHERE slug='camboja-news');
UPDATE editorial_profiles SET ownership_type='Radiodiffuseur public (société d''État de la Barbade)', owner='Caribbean Broadcasting Corporation (Gouvernement de la Barbade)', historical_context='Caribbean Broadcasting Corporation, radiodiffuseur national de la Barbade.',
  current_context='Actualité nationale barbadienne (santé, économie, politique) en anglais.', evidence_summary='Radiodiffuseur national de la Barbade ; propriété publique. Statut exact et gouvernance non vérifiés pour ce profil.', evidence_sources='[{"url": "https://www.cbc.bb/", "note": "Site officiel : Caribbean Broadcasting Corporation", "category": "self_description", "accessed_at": "2026-11-02"}]'::jsonb
  WHERE publisher_id=(SELECT id FROM publishers WHERE slug='cbc-barbados');
UPDATE editorial_profiles SET ownership_type='Quotidien privé', owner='Non vérifié (quotidien privé de Nassau)', historical_context='Quotidien de Nassau (Bahamas), l''un des principaux journaux du pays.',
  current_context='Actualité nationale bahaméenne, sports et économie en anglais.', evidence_summary='Quotidien privé de Nassau ; propriétaires actuels non vérifiés pour ce profil.', evidence_sources='[{"url": "https://www.tribune242.com/", "note": "Site officiel : The Tribune (Nassau)", "category": "self_description", "accessed_at": "2026-11-02"}]'::jsonb
  WHERE publisher_id=(SELECT id FROM publishers WHERE slug='the-tribune');
UPDATE editorial_profiles SET ownership_type='Radiodiffuseur public (société d''État des Bahamas)', owner='Broadcasting Corporation of The Bahamas (Gouvernement des Bahamas)', historical_context='ZNS, radiodiffuseur national des Bahamas (Broadcasting Corporation of The Bahamas).',
  current_context='Actualité gouvernementale et nationale bahaméenne en anglais (publie notamment les communiqués du Premier ministre).', evidence_summary='Radiodiffuseur national ; publie des communiqués officiels du gouvernement. Gouvernance non vérifiée pour ce profil.', evidence_sources='[{"url": "https://znsbahamas.com/", "note": "Site officiel : ZNS Bahamas", "category": "self_description", "accessed_at": "2026-11-02"}]'::jsonb
  WHERE publisher_id=(SELECT id FROM publishers WHERE slug='zns-bahamas');
SELECT p.slug, (ep.historical_context||ep.current_context||ep.evidence_summary||ep.ownership_type||ep.owner||ep.evidence_sources::text) ~ '\?' AS still_qmark, (ep.historical_context||ep.current_context||ep.evidence_summary||ep.ownership_type) ~ '[^-]' AS has_accents FROM editorial_profiles ep JOIN publishers p ON p.id=ep.publisher_id WHERE p.slug IN ('camboja-news','cbc-barbados','the-tribune','zns-bahamas') ORDER BY 1;
COMMIT;
